120	package hotel.reservations;
121	
122	import hotel.rooms.Room;
123	import java.math.BigDecimal;
124	import java.math.RoundingMode;
125	import java.time.LocalDate;
126	import java.time.Month;
127	
128	/**
129	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
130	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
131	 * (half-even) at every step.
132	 */
133	public final class PriceCalculator {
134	
135	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
136	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
137	
138	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
139	        return calculate(room, checkIn, checkOut, ratePlan, null);
140	    }
141	
142	    public Price calculate(
143	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
144	        RatePlan.StayDates stay = new RatePlan.StayDates(checkIn, checkOut, companyCode);
145	        ratePlan.validate(stay);
146	        int nights = 0;
147	        BigDecimal subtotal = cents(BigDecimal.ZERO);
148	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
149	            subtotal = subtotal.add(nightPrice(room, night));
150	            nights++;
151	        }
152	        Price plain = new Price(nights, subtotal, cents(BigDecimal.ZERO), subtotal);
153	        return ratePlan.adjust(room, stay, plain);
154	    }
155	
156	    BigDecimal nightPrice(Room room, LocalDate night) {
157	        BigDecimal nightlyRate = room.nightlyRate();
158	        if (isHighSeason(night)) {
159	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
160	        }
161	        return cents(nightlyRate);
162	    }
163	
164	    /** High season: from December 15 to the end of February, and the whole of July. */
165	    static boolean isHighSeason(LocalDate date) {
166	        Month month = date.getMonth();
167	        return month == Month.JANUARY
168	                || month == Month.FEBRUARY
169	                || month == Month.JULY
170	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
171	    }
172	
173	    static BigDecimal cents(BigDecimal value) {
174	        return value.setScale(2, RoundingMode.HALF_EVEN);
175	    }
176	}

